const root = process.cwd();
const output = path.resolve(process.argv[2] ?? path.join(root, "build", "stage6-release"));
const releaseInputs = path.resolve(process.argv[3] ?? output);
await mkdir(output, { recursive: true });
const digest = async file => createHash("sha256").update(await readFile(file)).digest("hex");
const subjects = [];

after.content:
  for (const name of (await readdir(directory)).sort()) {
    const absolute = path.join(directory, name);
    if ((await stat(absolute)).isDirectory()) await walk(absolute);
    else subjects.push({ name: path.relative(releaseInputs, absolute).replaceAll("\\", "/"), digest: { sha256: await digest(absolute) } });
  }
}
await walk(releaseInputs);
if (subjects.length === 0) throw new Error("provenance has no release subjects");
const materials = [".java-version", ".node-version", "gradle/wrapper/gradle-wrapper.properties",
  "gradle/libs.versions.toml", "pnpm-lock.yaml", "settings-gradle.lockfile", ".dockerignore",
  "deploy/relay/Relay.Dockerfile", "deploy/relay/Web.Dockerfile", "deploy/relay/Ingress.Dockerfile",
  "deploy/relay/compose.yaml", "scripts/generate-sbom.mjs", "scripts/generate-provenance.mjs",
  "scripts/sign-stage6-release.mjs", "scripts/generate-private-host-bundle.mjs"];
const head = execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim();
const sourceTree = execFileSync("git", ["stash", "create", "stage6-provenance"], { cwd: root, encoding: "utf8" }).trim() || head;
const statement = {
  _type: "https://in-toto.io/Statement/v1", subject: subjects,
  predicateType: "https://slsa.dev/provenance/v1",
  predicate: {
    buildDefinition: { buildType: "https://ji.invalid/build/stage6", externalParameters: { publicRelease: false },
      internalParameters: { baseCommit: head, sourceSnapshot: sourceTree },
      resolvedDependencies: await Promise.all(materials.map(async name => ({ uri: name, digest: { sha256: await digest(path.join(root, name)) } }))) },
    runDetails: { builder: { id: "ji-stage6-local-and-ubuntu" }, metadata: {
      invocationId: `${head}:${sourceTree}`, startedOn: new Date().toISOString(), finishedOn: new Date().toISOString() } },
  },
};
await writeFile(path.join(output, "provenance.intoto.jsonl"), `${JSON.stringify(statement)}\n`);
process.stdout.write(`PROVENANCE_SUBJECTS=${subjects.length}\nPROVENANCE_SOURCE_SNAPSHOT=${sourceTree}\n`);
